CREATE OR ALTER PROCEDURE [dbo].[uspPackingResult_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @PackingOrderId UNIQUEIDENTIFIER = NULL
	, @ProductionOutputId UNIQUEIDENTIFIER = NULL
	, @PackedQuantity DECIMAL(18,4) = NULL
	, @RejectedQuantity DECIMAL(18,4) = NULL
	, @PackagingType NVARCHAR(MAX) = NULL
	, @QualityStatus NVARCHAR(MAX) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[PackingOrderId]
			, j1.[PackingNo] AS [PackingOrderName]
			, t.[PlannedQty]
			, t.[DamagedQty]
			, t.[AcceptedQty]
			, t.[Remark]
			, t.[ProductionOutputId]
			, t.[PackedQuantity]
			, t.[RejectedQuantity]
			, t.[PackagingType]
			, t.[QualityStatus]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[PackingResult] AS t
		LEFT JOIN [dbo].[PackingOrder] AS j1 ON j1.[Id] = t.[PackingOrderId]
		WHERE 1 = 1
			AND (@PackingOrderId IS NULL OR t.[PackingOrderId] = @PackingOrderId)
			AND (@ProductionOutputId IS NULL OR t.[ProductionOutputId] = @ProductionOutputId)
			AND (@PackedQuantity IS NULL OR t.[PackedQuantity] = @PackedQuantity)
			AND (@RejectedQuantity IS NULL OR t.[RejectedQuantity] = @RejectedQuantity)
			AND (ISNULL(@PackagingType, '') = '' OR t.[PackagingType] LIKE CONCAT('%', @PackagingType, '%'))
			AND (ISNULL(@QualityStatus, '') = '' OR t.[QualityStatus] LIKE CONCAT('%', @QualityStatus, '%'))
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'packingOrderId' THEN r.[PackingOrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'packingOrderId' THEN r.[PackingOrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'packingOrderName' THEN r.[PackingOrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'packingOrderName' THEN r.[PackingOrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'plannedQty' THEN r.[PlannedQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'plannedQty' THEN r.[PlannedQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'damagedQty' THEN r.[DamagedQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'damagedQty' THEN r.[DamagedQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'acceptedQty' THEN r.[AcceptedQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'acceptedQty' THEN r.[AcceptedQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'remark' THEN r.[Remark] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'remark' THEN r.[Remark] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionOutputId' THEN r.[ProductionOutputId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionOutputId' THEN r.[ProductionOutputId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'packedQuantity' THEN r.[PackedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'packedQuantity' THEN r.[PackedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'rejectedQuantity' THEN r.[RejectedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'rejectedQuantity' THEN r.[RejectedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'packagingType' THEN r.[PackagingType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'packagingType' THEN r.[PackagingType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'qualityStatus' THEN r.[QualityStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'qualityStatus' THEN r.[QualityStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
